// Ids every edge shares (docs/seed-spec.md §4-§5, docs/architecture.md §8.2), as zod schemas: one
// definition for the BFF, the mocks' clients, the seed and the console. Complaint numbers are
// generated by code only (`R-AAAA-NNNNNN`, correlative per world and year), never by the model.
import { z } from "zod";

const SLUG = "[a-z0-9]+(?:-[a-z0-9]+)*";

/** An opaque id that is safe inside a storage key: no `#`, `/` or whitespace. */
export const Id = z.string().regex(/^[A-Za-z0-9][A-Za-z0-9._:+=@-]{0,159}$/, "invalid id");
export type Id = z.infer<typeof Id>;

/** `cus-0001`, `cus-1017`, `cus-qa-<runId>-<scenario>-<key>`. */
export const CustomerId = z.string().max(64).regex(new RegExp(`^cus-${SLUG}$`), "invalid customer id");
export type CustomerId = z.infer<typeof CustomerId>;

/** `stf-<slug>`: `stf-guest-NN`, `stf-qa-<role>`, `stf-operator-01`. */
export const StaffId = z.string().max(64).regex(new RegExp(`^stf-${SLUG}$`), "invalid staff id");
export type StaffId = z.infer<typeof StaffId>;

/** `L-0001`, `L-1017`: a loan of the simulated core. */
export const LoanId = z.string().max(64).regex(/^L-[A-Za-z0-9]+(?:-[A-Za-z0-9]+)*$/, "invalid loan id");
export type LoanId = z.infer<typeof LoanId>;

const COMPLAINT_NUMBER = /^R-(\d{4})-(\d{6})$/;
const MAX_SEQUENCE = 999_999;

/** `R-AAAA-NNNNNN`, correlative per world and year. */
export const ComplaintNumber = z.string().regex(COMPLAINT_NUMBER, "invalid complaint number");
export type ComplaintNumber = z.infer<typeof ComplaintNumber>;

/** The number of the `sequence`-th complaint of `year` (1-based): `complaintNumber(2026, 1)` = `R-2026-000001`. */
export function complaintNumber(year: number, sequence: number): ComplaintNumber {
  if (!Number.isInteger(year) || year < 2000 || year > 9999) throw new RangeError(`year out of range: ${year}`);
  if (!Number.isInteger(sequence) || sequence < 1 || sequence > MAX_SEQUENCE) throw new RangeError(`complaint sequence out of range: ${sequence}`);
  return `R-${year}-${String(sequence).padStart(6, "0")}`;
}

/** Year and sequence of a complaint number, or `undefined` for anything that is not one. */
export function parseComplaintNumber(value: string): { year: number; sequence: number } | undefined {
  const match = COMPLAINT_NUMBER.exec(value);
  if (!match) return undefined;
  const sequence = Number(match[2]);
  return sequence === 0 ? undefined : { year: Number(match[1]), sequence };
}
